insert into public.hq_catalogue (id, kind, title, ref, free, data) values
  ($j$verse:ps56-3$j$, 'verse', $j$Psalm 56:3$j$, $j$Psalm 56:3$j$, true, $j${"id": "ps56-3", "ref": "Psalm 56:3", "theme": "brave", "free": true, "short": "When I am afraid…", "text": "When I am afraid, I will put my trust in you."}$j$::jsonb),
  ($j$verse:josh1-9$j$, 'verse', $j$Joshua 1:9$j$, $j$Joshua 1:9$j$, false, $j${"id": "josh1-9", "ref": "Joshua 1:9", "theme": "brave", "text": "Haven’t I commanded you? Be strong and courageous. Don’t be afraid. Don’t be dismayed, for Yahweh your God is with you wherever you go."}$j$::jsonb),
  ($j$verse:ps46-1$j$, 'verse', $j$Psalm 46:1$j$, $j$Psalm 46:1$j$, false, $j${"id": "ps46-1", "ref": "Psalm 46:1", "theme": "brave", "text": "God is our refuge and strength, a very present help in trouble."}$j$::jsonb),
  ($j$verse:1pet5-7$j$, 'verse', $j$1 Peter 5:7$j$, $j$1 Peter 5:7$j$, false, $j${"id": "1pet5-7", "ref": "1 Peter 5:7", "theme": "brave", "text": "casting all your worries on him, because he cares for you."}$j$::jsonb),
  ($j$verse:ps118-24$j$, 'verse', $j$Psalm 118:24$j$, $j$Psalm 118:24$j$, true, $j${"id": "ps118-24", "ref": "Psalm 118:24", "theme": "thankful", "free": true, "text": "This is the day that Yahweh has made. We will rejoice and be glad in it!"}$j$::jsonb),
  ($j$verse:ps136-1$j$, 'verse', $j$Psalm 136:1$j$, $j$Psalm 136:1$j$, false, $j${"id": "ps136-1", "ref": "Psalm 136:1", "theme": "thankful", "text": "Give thanks to Yahweh, for he is good; for his loving kindness endures forever."}$j$::jsonb),
  ($j$verse:1thes5-16$j$, 'verse', $j$1 Thessalonians 5:16–18$j$, $j$1 Thessalonians 5:16–18$j$, false, $j${"id": "1thes5-16", "ref": "1 Thessalonians 5:16–18", "theme": "thankful", "text": "Always rejoice. Pray without ceasing. In everything give thanks, for this is the will of God in Christ Jesus toward you."}$j$::jsonb),
  ($j$verse:mt6-11$j$, 'verse', $j$Matthew 6:11$j$, $j$Matthew 6:11$j$, false, $j${"id": "mt6-11", "ref": "Matthew 6:11", "theme": "thankful", "text": "Give us today our daily bread."}$j$::jsonb),
  ($j$verse:eph4-32$j$, 'verse', $j$Ephesians 4:32$j$, $j$Ephesians 4:32$j$, true, $j${"id": "eph4-32", "ref": "Ephesians 4:32", "theme": "kind", "free": true, "text": "And be kind to one another, tender hearted, forgiving each other, just as God also in Christ forgave you."}$j$::jsonb),
  ($j$verse:1jn4-19$j$, 'verse', $j$1 John 4:19$j$, $j$1 John 4:19$j$, false, $j${"id": "1jn4-19", "ref": "1 John 4:19", "theme": "kind", "text": "We love him, because he first loved us."}$j$::jsonb),
  ($j$verse:jn13-34$j$, 'verse', $j$John 13:34$j$, $j$John 13:34$j$, false, $j${"id": "jn13-34", "ref": "John 13:34", "theme": "kind", "text": "A new commandment I give to you, that you love one another. Just as I have loved you, you also love one another."}$j$::jsonb),
  ($j$verse:1cor13-4$j$, 'verse', $j$1 Corinthians 13:4$j$, $j$1 Corinthians 13:4$j$, false, $j${"id": "1cor13-4", "ref": "1 Corinthians 13:4", "theme": "kind", "text": "Love is patient and is kind. Love doesn’t envy. Love doesn’t brag, is not proud,"}$j$::jsonb),
  ($j$verse:ps4-8$j$, 'verse', $j$Psalm 4:8$j$, $j$Psalm 4:8$j$, true, $j${"id": "ps4-8", "ref": "Psalm 4:8", "theme": "peace", "free": true, "text": "In peace I will both lay myself down and sleep, for you, Yahweh alone, make me live in safety."}$j$::jsonb),
  ($j$verse:ps23-1$j$, 'verse', $j$Psalm 23:1$j$, $j$Psalm 23:1$j$, false, $j${"id": "ps23-1", "ref": "Psalm 23:1", "theme": "peace", "text": "Yahweh is my shepherd: I shall lack nothing."}$j$::jsonb),
  ($j$verse:ps119-105$j$, 'verse', $j$Psalm 119:105$j$, $j$Psalm 119:105$j$, false, $j${"id": "ps119-105", "ref": "Psalm 119:105", "theme": "peace", "text": "Your word is a lamp to my feet, and a light for my path."}$j$::jsonb),
  ($j$verse:num6-24$j$, 'verse', $j$Numbers 6:24–26$j$, $j$Numbers 6:24–26$j$, false, $j${"id": "num6-24", "ref": "Numbers 6:24–26", "theme": "peace", "text": "Yahweh bless you, and keep you. Yahweh make his face to shine on you, and be gracious to you. Yahweh lift up his face toward you, and give you peace."}$j$::jsonb),
  ($j$verse:jn3-16$j$, 'verse', $j$John 3:16$j$, $j$John 3:16$j$, true, $j${"id": "jn3-16", "ref": "John 3:16", "theme": "jesus", "free": true, "text": "For God so loved the world, that he gave his one and only Son, that whoever believes in him should not perish, but have eternal life."}$j$::jsonb),
  ($j$verse:mt19-14$j$, 'verse', $j$Matthew 19:14$j$, $j$Matthew 19:14$j$, false, $j${"id": "mt19-14", "ref": "Matthew 19:14", "theme": "jesus", "text": "But Jesus said, “Allow the little children, and don’t forbid them to come to me; for the Kingdom of Heaven belongs to ones like these.”"}$j$::jsonb),
  ($j$verse:lk2-11$j$, 'verse', $j$Luke 2:11$j$, $j$Luke 2:11$j$, false, $j${"id": "lk2-11", "ref": "Luke 2:11", "theme": "jesus", "text": "For there is born to you today, in David’s city, a Savior, who is Christ the Lord."}$j$::jsonb),
  ($j$verse:jn10-11$j$, 'verse', $j$John 10:11$j$, $j$John 10:11$j$, false, $j${"id": "jn10-11", "ref": "John 10:11", "theme": "jesus", "text": "I am the good shepherd. The good shepherd lays down his life for the sheep."}$j$::jsonb),
  ($j$verse:gen1-1$j$, 'verse', $j$Genesis 1:1$j$, $j$Genesis 1:1$j$, true, $j${"id": "gen1-1", "ref": "Genesis 1:1", "theme": "made", "free": true, "text": "In the beginning, God created the heavens and the earth."}$j$::jsonb),
  ($j$verse:ps139-14$j$, 'verse', $j$Psalm 139:14$j$, $j$Psalm 139:14$j$, false, $j${"id": "ps139-14", "ref": "Psalm 139:14", "theme": "made", "text": "I will give thanks to you, for I am fearfully and wonderfully made. Your works are wonderful. My soul knows that very well."}$j$::jsonb),
  ($j$verse:ps19-1$j$, 'verse', $j$Psalm 19:1$j$, $j$Psalm 19:1$j$, false, $j${"id": "ps19-1", "ref": "Psalm 19:1", "theme": "made", "text": "The heavens declare the glory of God. The expanse shows his handiwork."}$j$::jsonb),
  ($j$verse:ps150-6$j$, 'verse', $j$Psalm 150:6$j$, $j$Psalm 150:6$j$, false, $j${"id": "ps150-6", "ref": "Psalm 150:6", "theme": "made", "text": "Let everything that has breath praise Yah! Praise Yah!"}$j$::jsonb),
  ($j$verse:gen9-13$j$, 'verse', $j$Genesis 9:13$j$, $j$Genesis 9:13$j$, false, $j${"id": "gen9-13", "ref": "Genesis 9:13", "theme": "made", "text": "I set my rainbow in the cloud, and it will be a sign of a covenant between me and the earth."}$j$::jsonb),
  ($j$verse:prov3-5$j$, 'verse', $j$Proverbs 3:5$j$, $j$Proverbs 3:5$j$, false, $j${"id": "prov3-5", "ref": "Proverbs 3:5", "theme": "brave", "text": "Trust in Yahweh with all your heart, and don’t lean on your own understanding."}$j$::jsonb),
  ($j$verse:lk15-6$j$, 'verse', $j$Luke 15:6$j$, $j$Luke 15:6$j$, false, $j${"id": "lk15-6", "ref": "Luke 15:6", "theme": "jesus", "text": "When he comes home, he calls together his friends and his neighbors, saying to them, ‘Rejoice with me, for I have found my sheep which was lost!’"}$j$::jsonb),
  ($j$story:creation$j$, 'story', $j$God Made Everything$j$, $j$Genesis 1–2$j$, true, $j${"id": "creation", "title": "God Made Everything", "ref": "Genesis 1–2", "scene": "creation", "free": true, "minutes": 4, "verse": "gen1-1", "pages": ["In the very beginning, there was nothing at all. No sky. No sea. No you or me. But God was there.", "God said, “Let there be light!” And light shone out, bright and warm. God called the light “day” and the darkness “night.”", "God made the big blue sky and the wide, splashy sea. He gathered dry land and filled it with trees, flowers and fruit.", "God hung the sun to shine by day, and the moon and twinkly stars to glow by night.", "God filled the sea with fish and whales, and the sky with birds. He made animals that hop, crawl, stomp and run.", "Then God made people, a man and a woman, in his own image. He loved them, and he gave them his world to care for.", "God looked at everything he had made, and it was very good. On the seventh day, God rested."], "talk": ["What is your favorite thing God made?", "Why do you think God made people?", "How can we take care of God’s world today?"], "pray": "Dear God, thank you for making the sky, the sea, the animals and me. Help me take care of your world. Amen."}$j$::jsonb),
  ($j$story:noah$j$, 'story', $j$Noah and the Rainbow Promise$j$, $j$Genesis 6–9$j$, true, $j${"id": "noah", "title": "Noah and the Rainbow Promise", "ref": "Genesis 6–9", "scene": "noah", "free": true, "minutes": 4, "verse": "gen9-13", "pages": ["Long ago, many people forgot about God and chose to do wrong. But one man, Noah, loved God and listened to him.", "God told Noah, “Build a big boat called an ark. A great flood is coming, and I will keep you and your family safe.”", "Noah built and built. Bang, bang, bang! People may have laughed, but Noah kept on obeying God.", "Then the animals came, two by two: lions and lambs, elephants and ants. Noah’s family went inside, and God shut the door.", "Rain fell for forty days and forty nights. Water covered everything, but the ark floated safely on top.", "At last the rain stopped. Noah sent out a dove, and it came back with an olive leaf. Dry land was near!", "Everyone stepped out onto the clean new earth. God put a rainbow in the sky as a promise that he would never flood the whole earth again."], "talk": ["How did Noah show that he trusted God?", "What do you think it was like inside the ark?", "What does a rainbow remind us about God?"], "pray": "Dear God, thank you for keeping your promises. When I see a rainbow, help me remember that you are faithful. Amen."}$j$::jsonb),
  ($j$story:storm$j$, 'story', $j$Jesus Calms the Storm$j$, $j$Mark 4:35–41$j$, true, $j${"id": "storm", "title": "Jesus Calms the Storm", "ref": "Mark 4:35–41", "scene": "storm", "free": true, "minutes": 3, "verse": "ps56-3", "pages": ["One evening, Jesus said to his friends, “Let’s go across the lake.” They climbed into a boat and pushed off from the shore.", "Jesus was tired after a busy day. He lay down at the back of the boat, put his head on a cushion and fell fast asleep.", "Suddenly the wind began to howl. Whoosh! Big waves crashed over the sides, and the boat began to fill with water.", "His friends were very afraid. They shook Jesus awake. “Teacher, don’t you care that we’re sinking?”", "Jesus stood up. He spoke to the wind and the waves: “Peace! Be still!” And everything became completely calm.", "“Why were you so afraid?” Jesus asked his friends. They looked at each other in wonder. “Even the wind and the sea obey him!”"], "talk": ["What makes you feel afraid?", "What did Jesus do when his friends were scared?", "What can we do when we feel afraid?"], "pray": "Jesus, when I feel scared, help me remember that you are with me and you are stronger than any storm. Amen."}$j$::jsonb),
  ($j$story:lost-sheep$j$, 'story', $j$The Lost Sheep$j$, $j$Luke 15:3–7$j$, true, $j${"id": "lost-sheep", "title": "The Lost Sheep", "ref": "Luke 15:3–7", "scene": "sheep", "free": true, "minutes": 3, "verse": "lk15-6", "pages": ["Jesus told a story about a shepherd who had one hundred sheep. He knew every one of them, and he loved them all.", "Each day he led them to green grass and cool water. Each night he counted them: ninety-eight, ninety-nine, one hundred.", "But one night he counted: ninety-seven, ninety-eight, ninety-nine… One little sheep was missing!", "The shepherd left the ninety-nine safe together and went out to look. Over the hills and through the bushes, he called and searched.", "At last he heard a small “Baa!” There was his sheep! He lifted it onto his shoulders and carried it all the way home.", "“Celebrate with me!” he told his friends. “I found my lost sheep!” Jesus said God loves us like that shepherd, and heaven is full of joy when someone comes home to him."], "talk": ["How do you think the little sheep felt when it was found?", "Why didn’t the shepherd just stay with the ninety-nine?", "How does God show that he loves you?"], "pray": "Dear God, thank you that you know my name and you never stop looking for me. Amen."}$j$::jsonb),
  ($j$story:moses$j$, 'story', $j$Baby Moses in the Basket$j$, $j$Exodus 1–2$j$, false, $j${"id": "moses", "title": "Baby Moses in the Basket", "ref": "Exodus 1–2", "scene": "moses", "minutes": 4, "verse": "prov3-5", "pages": ["Long ago in Egypt, God’s people, the Israelites, were slaves. The king, called Pharaoh, made a cruel rule that put their baby boys in danger.", "One mother had a beautiful baby boy. She hid him at home for three months, keeping him safe and quiet.", "When he grew too big to hide, she made a basket, coated it so water couldn’t get in, and laid her baby gently inside.", "She set the basket among the tall reeds by the river. His big sister, Miriam, watched from nearby to see what would happen.", "Pharaoh’s daughter came down to the river and saw the basket. The baby was crying! She felt sorry for him and wanted to keep him.", "Brave Miriam stepped forward. “Shall I find a woman to help feed the baby?” She ran and brought back the baby’s own mother!", "The princess named him Moses. God had kept him safe, and one day God would use Moses to lead his people to freedom."], "talk": ["How did Moses’ mom and sister show courage?", "Who does God use to keep you safe?", "Can you remember a time God took care of you?"], "pray": "Dear God, thank you for the people who take care of me. Help me trust you, even when I don’t know what will happen. Amen."}$j$::jsonb),
  ($j$story:david$j$, 'story', $j$David and the Giant$j$, $j$1 Samuel 17$j$, false, $j${"id": "david", "title": "David and the Giant", "ref": "1 Samuel 17", "scene": "david", "minutes": 4, "verse": "josh1-9", "pages": ["David was a shepherd boy who cared for his father’s sheep. Out in the fields, he learned that God was always with him.", "One day David took food to his big brothers in King Saul’s army. There he heard a booming voice.", "It was Goliath, a giant soldier taller than anyone! “Who will come and fight me?” he roared. All the soldiers were afraid.", "“I’ll go,” said David. “God helped me protect my sheep from a lion and a bear. He will help me now.”", "David didn’t take armor or a sword. He picked five smooth stones from a stream and took his shepherd’s sling.", "“You come with a sword,” David called, “but I come in the name of the Lord!” He swung his sling, a stone flew, and the giant fell down.", "Everyone could see it: the battle belonged to God. David was small, but his God was big."], "talk": ["Why wasn’t David afraid?", "What feels like a “giant” to you right now?", "How can God help you be brave?"], "pray": "Dear God, when things feel too big for me, remind me that nothing is too big for you. Amen."}$j$::jsonb),
  ($j$story:daniel$j$, 'story', $j$Daniel and the Lions$j$, $j$Daniel 6$j$, false, $j${"id": "daniel", "title": "Daniel and the Lions", "ref": "Daniel 6", "scene": "daniel", "minutes": 4, "verse": "ps46-1", "pages": ["Daniel loved God. Three times every day he knelt by his window to pray and to thank God.", "Daniel worked for King Darius, and he did such good work that the king planned to put him in charge of the whole kingdom.", "Some jealous men wanted to get Daniel into trouble. They tricked the king into making a new law: for thirty days, people could pray only to the king.", "Daniel heard about the law, but he kept praying to God, just as he always had. The men ran to tell the king.", "The king was very sad, but he had to keep his law. Daniel was put into a den full of lions, and a big stone covered the door.", "All night long, the king couldn’t sleep. At sunrise he hurried to the den. “Daniel! Did your God save you?”", "“My God sent his angel and shut the lions’ mouths!” Daniel called. The king was overjoyed and told everyone to honor Daniel’s God."], "talk": ["Why did Daniel keep praying?", "When can you talk to God during your day?", "How did God take care of Daniel?"], "pray": "Dear God, I’m glad I can talk to you anytime. Help me be faithful like Daniel. Amen."}$j$::jsonb),
  ($j$story:jonah$j$, 'story', $j$Jonah and the Big Fish$j$, $j$Jonah 1–3$j$, false, $j${"id": "jonah", "title": "Jonah and the Big Fish", "ref": "Jonah 1–3", "scene": "jonah", "minutes": 4, "verse": "ps136-1", "pages": ["God told Jonah, “Go to the big city of Nineveh and tell the people to stop doing wrong.”", "But Jonah didn’t want to go. He ran the other way and got on a ship sailing far, far away.", "Out at sea, God sent a great wind. The storm tossed the ship, and the sailors were terrified.", "“This is my fault,” Jonah said. “I ran from God. Throw me into the sea, and it will be calm.” Splash! The sea grew still.", "God sent a huge fish to swallow Jonah. For three days and three nights, Jonah was inside the fish. He prayed and thanked God for saving him.", "Then the fish spat Jonah out onto dry land. God spoke to Jonah again: “Go to Nineveh.” This time, Jonah went.", "The people of Nineveh listened. They told God they were sorry and changed their ways, and God forgave them. God loves to give second chances."], "talk": ["Why do you think Jonah ran away?", "What did Jonah do inside the fish?", "Is there someone you need to forgive, or to say sorry to?"], "pray": "Dear God, thank you for second chances. Help me listen to you and obey, even when it’s hard. Amen."}$j$::jsonb),
  ($j$song:jesus-loves-me$j$, 'song', $j$Jesus Loves Me$j$, null, true, $j${"id": "jesus-loves-me", "title": "Jesus Loves Me", "credit": "Anna B. Warner, 1860 · tune William B. Bradbury, 1862", "free": true, "mood": "Anytime", "verses": [["Jesus loves me! This I know,", "For the Bible tells me so;", "Little ones to Him belong;", "They are weak, but He is strong."], ["Yes, Jesus loves me!", "Yes, Jesus loves me!", "Yes, Jesus loves me!", "The Bible tells me so."], ["Jesus loves me! He who died", "Heaven’s gate to open wide;", "He will wash away my sin,", "Let His little child come in."]]}$j$::jsonb),
  ($j$song:doxology$j$, 'song', $j$The Doxology$j$, null, true, $j${"id": "doxology", "title": "The Doxology", "credit": "Thomas Ken, 1674 · tune Old Hundredth, 1551", "free": true, "mood": "Mealtime & mornings", "verses": [["Praise God, from whom all blessings flow;", "Praise Him, all creatures here below;", "Praise Him above, ye heavenly host;", "Praise Father, Son, and Holy Ghost. Amen."]]}$j$::jsonb),
  ($j$song:tender-shepherd$j$, 'song', $j$Jesus, Tender Shepherd, Hear Me$j$, null, true, $j${"id": "tender-shepherd", "title": "Jesus, Tender Shepherd, Hear Me", "credit": "Mary L. Duncan, 1839", "free": true, "mood": "Bedtime", "verses": [["Jesus, tender Shepherd, hear me;", "Bless Thy little lamb tonight;", "Through the darkness be Thou near me,", "Keep me safe till morning light."], ["All this day Thy hand has led me,", "And I thank Thee for Thy care;", "Thou hast clothed me, warmed and fed me;", "Listen to my evening prayer."], ["Let my sins be all forgiven;", "Bless the friends I love so well;", "Take us all at last to heaven,", "Happy there with Thee to dwell."]]}$j$::jsonb),
  ($j$song:bright-beautiful$j$, 'song', $j$All Things Bright and Beautiful$j$, null, false, $j${"id": "bright-beautiful", "title": "All Things Bright and Beautiful", "credit": "Cecil Frances Alexander, 1848", "mood": "Creation & outdoors", "verses": [["All things bright and beautiful,", "All creatures great and small,", "All things wise and wonderful,", "The Lord God made them all."], ["Each little flower that opens,", "Each little bird that sings,", "He made their glowing colours,", "He made their tiny wings."]]}$j$::jsonb),
  ($j$song:sunbeam$j$, 'song', $j$Jesus Wants Me for a Sunbeam$j$, null, false, $j${"id": "sunbeam", "title": "Jesus Wants Me for a Sunbeam", "credit": "Nellie Talbot, 1900", "mood": "Mornings & kindness", "verses": [["Jesus wants me for a sunbeam,", "To shine for Him each day;", "In every way try to please Him,", "At home, at school, at play."], ["A sunbeam, a sunbeam,", "Jesus wants me for a sunbeam;", "A sunbeam, a sunbeam,", "I’ll be a sunbeam for Him."]]}$j$::jsonb),
  ($j$song:away-manger$j$, 'song', $j$Away in a Manger$j$, null, false, $j${"id": "away-manger", "title": "Away in a Manger", "credit": "Anonymous, 1885", "mood": "Christmas & bedtime", "verses": [["Away in a manger, no crib for a bed,", "The little Lord Jesus laid down His sweet head.", "The stars in the sky looked down where He lay,", "The little Lord Jesus asleep on the hay."], ["The cattle are lowing, the Baby awakes,", "But little Lord Jesus, no crying He makes;", "I love Thee, Lord Jesus! Look down from the sky,", "And stay by my cradle till morning is nigh."]]}$j$::jsonb),
  ($j$song:amazing-grace$j$, 'song', $j$Amazing Grace$j$, null, false, $j${"id": "amazing-grace", "title": "Amazing Grace", "credit": "John Newton, 1779", "mood": "Family worship", "verses": [["Amazing grace! how sweet the sound", "That saved a wretch like me!", "I once was lost, but now am found;", "Was blind, but now I see."]]}$j$::jsonb),
  ($j$prayer:morning$j$, 'prayer', $j$Good morning, God$j$, null, false, $j${"id": "morning", "title": "Good morning, God", "when": "Morning", "text": "Good morning, God! Thank you for this brand-new day. Help me to be kind, to listen, and to know that you are with me everywhere I go. Amen."}$j$::jsonb),
  ($j$prayer:grace$j$, 'prayer', $j$Mealtime grace$j$, null, false, $j${"id": "grace", "title": "Mealtime grace", "when": "Meals", "text": "God is great, God is good, and we thank Him for our food. Amen.", "note": "Traditional"}$j$::jsonb),
  ($j$prayer:grace-2$j$, 'prayer', $j$Thank-you grace$j$, null, false, $j${"id": "grace-2", "title": "Thank-you grace", "when": "Meals", "text": "Thank you, God, for this food, for the hands that made it, and for the people around this table. Amen."}$j$::jsonb),
  ($j$prayer:bedtime$j$, 'prayer', $j$Bedtime prayer$j$, null, false, $j${"id": "bedtime", "title": "Bedtime prayer", "when": "Bedtime", "text": "Dear Jesus, thank you for today. Thank you for (name the good things). I’m sorry for (name anything hard). Please keep my family safe tonight. Amen."}$j$::jsonb),
  ($j$prayer:worry$j$, 'prayer', $j$When I feel worried$j$, null, false, $j${"id": "worry", "title": "When I feel worried", "when": "Anytime", "text": "God, I feel worried about (name it). I give it to you, because you care for me. Help me feel your peace. Amen."}$j$::jsonb),
  ($j$prayer:lords-prayer$j$, 'prayer', $j$The Lord’s Prayer$j$, null, false, $j${"id": "lords-prayer", "title": "The Lord’s Prayer", "when": "Anytime", "ref": "Matthew 6:9–13, WEB", "text": "Our Father in heaven, may your name be kept holy. Let your Kingdom come. Let your will be done on earth as it is in heaven. Give us today our daily bread. Forgive us our debts, as we also forgive our debtors. Bring us not into temptation, but deliver us from the evil one. For yours is the Kingdom, the power, and the glory forever. Amen."}$j$::jsonb),
  ($j$prayer:blessing$j$, 'prayer', $j$A parent’s blessing$j$, null, false, $j${"id": "blessing", "title": "A parent’s blessing", "when": "Bedtime", "ref": "Numbers 6:24–26, WEB", "text": "Yahweh bless you, and keep you. Yahweh make his face to shine on you, and be gracious to you. Yahweh lift up his face toward you, and give you peace."}$j$::jsonb),
  ($j$routine:morning$j$, 'routine', $j$Morning with God$j$, null, true, $j${"id": "morning", "name": "Morning with God", "at": "07:00", "days": [1, 2, 3, 4, 5], "free": true, "note": "This is the day the Lord has made.", "steps": ["pray", "dressed", "breakfast", "teeth", "verse", "backpack"]}$j$::jsonb),
  ($j$routine:bedtime$j$, 'routine', $j$Bedtime blessings$j$, null, true, $j${"id": "bedtime", "name": "Bedtime blessings", "at": "19:30", "days": [0, 1, 2, 3, 4, 5, 6], "free": true, "note": "In peace I will lie down and sleep.", "steps": ["pajamas", "teeth", "bible", "thanks", "pray", "sleep"]}$j$::jsonb),
  ($j$routine:meal$j$, 'routine', $j$Mealtime grace$j$, null, true, $j${"id": "meal", "name": "Mealtime grace", "at": "12:00", "days": [0, 1, 2, 3, 4, 5, 6], "free": true, "note": "Give us today our daily bread.", "steps": ["hands", "grace", "breakfast", "thanks"]}$j$::jsonb),
  ($j$routine:sunday$j$, 'routine', $j$Sunday church morning$j$, null, false, $j${"id": "sunday", "name": "Sunday church morning", "at": "08:00", "days": [0], "note": "Come before his presence with singing.", "steps": ["dressed", "breakfast", "shoes", "sing", "church"]}$j$::jsonb),
  ($j$routine:faith-night$j$, 'routine', $j$Family faith night$j$, null, false, $j${"id": "faith-night", "name": "Family faith night", "at": "18:30", "days": [5], "note": "Ten minutes together around God’s Word.", "steps": ["tidy", "bible", "feeling", "pray", "sing", "bless"]}$j$::jsonb),
  ($j$routine:kindness$j$, 'routine', $j$After-school kindness$j$, null, false, $j${"id": "kindness", "name": "After-school kindness", "at": "15:30", "days": [1, 2, 3, 4, 5], "note": "Be kind to one another.", "steps": ["hands", "snack", "kind", "tidy", "thanks"]}$j$::jsonb),
  ($j$routine:screen$j$, 'routine', $j$Screens off, hearts on$j$, null, false, $j${"id": "screen", "name": "Screens off, hearts on", "at": "17:00", "days": [0, 6], "note": "Finish, check in, then play.", "steps": ["screen", "feeling", "pray", "blocks", "tidy"]}$j$::jsonb),
  ($j$faith_night:light$j$, 'faith_night', $j$You are the light$j$, $j$Matthew 5:14–16$j$, true, $j${"id": "light", "title": "You are the light", "free": true, "minutes": 10, "read": "Matthew 5:14–16", "open": "Turn off the lights and light one candle (or a torch). What happens to the dark?", "talk": ["Jesus says his followers are like light. What could ‘shining’ look like at school or at home this week?", "Who has been a light to you lately?"], "do": "Each person names one kind thing they’ll do this week. Write them on a sticky note on the fridge.", "pray": "Take turns: ‘God, help me shine by…’"}$j$::jsonb),
  ($j$faith_night:manna$j$, 'faith_night', $j$God gives what we need$j$, $j$Exodus 16:1–18$j$, false, $j${"id": "manna", "title": "God gives what we need", "minutes": 10, "read": "Exodus 16:1–18", "open": "Put a small snack on a plate for each person. Who gave us this food? Who gave it to them?", "talk": ["How did God feed his people in the desert every single day?", "What do we need God’s help with today?"], "do": "Make a ‘daily bread’ jar: write one thing God gave you today on a slip and drop it in.", "pray": "Pray the Lord’s Prayer together, slowly."}$j$::jsonb),
  ($j$faith_night:good-samaritan$j$, 'faith_night', $j$Who is my neighbor?$j$, $j$Luke 10:25–37$j$, false, $j${"id": "good-samaritan", "title": "Who is my neighbor?", "minutes": 12, "read": "Luke 10:25–37", "open": "Act the story out with toys or stuffed animals. Who walked past? Who stopped?", "talk": ["Why do you think the first two people walked by?", "Who is someone that might need us to stop and help?"], "do": "Plan one ‘neighbor surprise’: a card, a drawing, or helping carry groceries.", "pray": "Pray for someone by name who needs help this week."}$j$::jsonb),
  ($j$faith_night:zacchaeus$j$, 'faith_night', $j$Jesus came to my house$j$, $j$Luke 19:1–10$j$, false, $j${"id": "zacchaeus", "title": "Jesus came to my house", "minutes": 10, "read": "Luke 19:1–10", "open": "Climb up high (safely!) on a chair. What can you see from up here?", "talk": ["How do you think Zacchaeus felt when Jesus said his name?", "What changed after Jesus came to his house?"], "do": "Say ‘Jesus knows my name’ and write each family member’s name on a paper tree.", "pray": "Thank Jesus that he knows each of us by name."}$j$::jsonb)
