-- The four AI employees and the MVP content catalogue they work from.
-- Re-running this file refreshes the catalogue and resets nothing else.

on conflict (id) do update set name = excluded.name, role = excluded.role, look = excluded.look, sort = excluded.sort;

on conflict (id) do update set kind = excluded.kind, title = excluded.title, ref = excluded.ref, free = excluded.free, data = excluded.data;
